    private Message sentTo(String address) {
        return sentMessages.all().stream().filter(m -> m.to().equals(address)).findFirst().orElseThrow();
    }

    @Test
    void confirmingTellsHousekeepingAndFinance() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));

        service.confirm(reservation.id());

        Message housekeeping = sentTo("governanca@pousadamarealta.com.br");
        assertEquals("Reserva confirmada - quarto 201", housekeeping.subject());
        assertTrue(housekeeping.body().contains("10/03/2027"));
        assertTrue(housekeeping.body().contains("13/03/2027"));
        assertTrue(housekeeping.body().contains("2"));
        Message finance = sentTo("financeiro@pousadamarealta.com.br");
        assertEquals("Pagamento recebido - reserva " + reservation.id(), finance.subject());
        assertTrue(finance.body().contains("R$ 1.234,56".replace("1.234,56", "1.249,50")));
    }

    @Test
    void cancellingAConfirmedReservationTellsHousekeepingAndFinanceAboutTheRefund() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
        service.confirm(reservation.id());
        int before = sentMessages.all().size();

        service.cancel(reservation.id());

        List<Message> sent = sentMessages.all().subList(before, sentMessages.all().size());
        assertEquals(2, sent.size());
        Message housekeeping = sentTo("governanca@pousadamarealta.com.br");
        assertEquals("Reserva confirmada - quarto 201", housekeeping.subject());
        Message cancelled = sent.stream().filter(m -> m.to().startsWith("governanca")).findFirst().orElseThrow();
        assertEquals("Reserva cancelada - quarto 201", cancelled.subject());
        assertTrue(cancelled.body().contains("10/03/2027"));
        Message refund = sent.stream().filter(m -> m.to().startsWith("financeiro")).findFirst().orElseThrow();
        assertEquals("Reembolso - reserva " + reservation.id(), refund.subject());
        assertTrue(refund.body().contains("R$ 1.249,50"));
    }

    @Test
    void cancellingWithNothingToRefundDoesNotTellFinance() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-11", 1, RatePlan.NON_REFUNDABLE));
        service.confirm(reservation.id());
        int before = sentMessages.all().size();

        service.cancel(reservation.id());

        List<Message> sent = sentMessages.all().subList(before, sentMessages.all().size());
        assertEquals(1, sent.size());
        assertEquals("governanca@pousadamarealta.com.br", sent.get(0).to());
    }

    @Test
    void cancellingAPendingReservationTellsNobody() {
        Reservation reservation = service.create(stay(201, "2027-03-10", "2027-03-11", 1, RatePlan.STANDARD));

        service.cancel(reservation.id());

        assertEquals(0, sentMessages.all().size());
    }
}
